<template>
  <div class="payroll-workbench" v-loading="loadingSheet">
    <section v-if="detailOnly && loadingSheet && !sheet" class="card-compact empty-sheet">正在加载工资明细…</section>
    <section v-if="detailOnly && loadError" class="card-compact"><el-alert :title="loadError" type="error" :closable="false" /><el-button @click="loadSavedSheet(props.sheetId)">重新加载</el-button></section>
    <section v-if="!detailOnly" class="payroll-hero"><div><span class="eyebrow">{{ reviewOnly ? '人事专区 · 工资审核' : '人事专区 · 工资表制作' }}</span><h2>{{ reviewOnly ? '工资审核工作台' : '月度工资工作台' }}</h2><p>{{ reviewOnly ? '集中查看待审核工资表，核对出勤与工资明细，审核通过或退回修改。' : '自动生成员工与薪酬快照，再录入当月出勤、加班、奖罚和扣缴，保存后提交审核，审核通过后导出正式工资表。' }}</p></div><div class="sheet-count"><b>{{ savedSheets.length }}</b><span>待处理工资表</span></div></section>
    <section v-if="!reviewOnly && !detailOnly" class="payroll-controls card-compact"><el-form inline class="sheet-form"><el-form-item label="员工归属"><span v-if="context.own_only">{{ form.store_name }}</span><StoreRegionSelect v-else v-model="affiliation" :stores="stores" show-group :clearable="false" input-width="250px" placeholder="选择门店 / 集团" /></el-form-item><el-form-item label="工资月份"><el-date-picker v-model="form.period" type="month" value-format="YYYY-MM" style="width:150px" @change="loadMonthSetting" /></el-form-item><el-button v-if="context.can_prepare" type="primary" :loading="preparing" @click="prepareSheet">生成 / 打开</el-button></el-form><span class="control-note">相同门店和月份会打开已保存工资表，不覆盖历史数据。</span></section>
    <section v-if="!reviewOnly && !detailOnly" class="card-compact"><span>{{ form.period }} 应出勤：集团 {{ monthSettings.group.published_at ? monthSettings.group.scheduled_days+' 天' : '未提交' }} · 门店 {{ monthSettings.store.published_at ? monthSettings.store.scheduled_days+' 天' : '未提交' }}</span><el-button v-if="context.can_attendance" link type="primary" @click="router.push('/staff-management/attendance')">前往月出勤管理</el-button></section>
    <section v-if="sheet" class="payroll-sheet card-compact"><header class="sheet-header"><div><h3>{{ sheet.store_name }} · {{ sheet.period }} 工资表</h3><p>共 {{ sheet.items.length }} 人 · {{ sheet.status || '草稿' }} · 最后更新 {{ sheet.updated_at || '刚刚' }}</p></div><div class="sheet-actions"><el-button v-if="sheet.can_edit" :loading="saving" @click="saveSheet">保存明细</el-button><el-button v-if="sheet.can_edit_deductions && !sheet.can_edit" :loading="saving" @click="saveDeductions">保存代扣代缴</el-button><el-button v-if="sheet.can_submit" type="primary" :loading="saving" @click="submitSheet">保存并提交审核</el-button><el-button v-if="detailOnly && sheet.can_review" type="success" @click="reviewSheet('approve')">审核通过</el-button><el-button v-if="detailOnly && sheet.can_review" type="warning" @click="reviewSheet('return')">退回修改</el-button><el-button :type="sheet.status==='已审核'?'success':'default'" :disabled="!sheet.id" @click="downloadSheet">{{ sheet.status==='已审核'?'导出正式 Excel':'导出未审核预览' }}</el-button></div></header><div class="summary-grid"><div><small>员工数</small><b>{{ sheet.items.length }}</b></div><div><small>应发工资</small><b>￥{{ summary.gross.toFixed(2) }}</b></div><div><small>代扣合计</small><b class="deduct">￥{{ summary.deductions.toFixed(2) }}</b></div><div><small>实发工资</small><b class="net">￥{{ summary.net.toFixed(2) }}</b></div></div>
      <div class="sheet-scroll"><el-table :data="sheet.items" border size="small" row-key="id" class="payroll-table">
        <el-table-column label="序号" width="62" fixed><template #default="{ $index }">{{ $index + 1 }}</template></el-table-column><el-table-column prop="name" label="姓名" width="100" fixed /><el-table-column prop="position" label="职务" width="92" /><el-table-column prop="entry_date" label="入职日期" width="104" /><el-table-column label="本月应出勤" width="100"><template #default="{ row }">{{ row.payroll_base_days || row.scheduled_days }} 天</template></el-table-column><el-table-column label="工资承担" min-width="230"><template #default="{ row }"><span v-if="row.is_dispatch_support">支援店承担 {{ row.support_days }} 天<br><small>原归属：{{ row.dispatch_origin_store_name }}</small><br><small>支援日期：{{ (row.dispatch_dates || []).join('、') }}（人事登记）</small></span><span v-else>本店承担 {{ actualDays(row) }} 天</span></template></el-table-column>
        <el-table-column label="出勤"><el-table-column v-for="column in attendanceColumns" :key="column.key" :label="column.label" width="106"><template #default="{ row }"><el-input v-model="row[column.key]" inputmode="decimal" :disabled="!sheet.can_edit" size="small" class="cell-number" /></template></el-table-column><el-table-column label="实际出勤" width="90"><template #default="{ row }"><el-input :model-value="actualDays(row)" @update:model-value="value=>setOverride(row,'actual_days',value)" inputmode="decimal" :disabled="!sheet.can_edit" size="small" class="cell-number" /></template></el-table-column></el-table-column>
        <el-table-column label="标准工资"><el-table-column v-for="column in salaryColumns" :key="column.key" :label="column.label" width="118"><template #default="{ row }"><span>￥{{ n(row[column.key]).toFixed(2) }}</span></template></el-table-column><el-table-column label="标准工资" width="110"><template #default="{ row }">￥{{ standardSalary(row).toFixed(2) }}</template></el-table-column></el-table-column>
        <el-table-column label="实际出勤工资"><el-table-column label="基本工资" width="112"><template #default="{ row }"><el-input :model-value="actualComponent(row,'base_salary')" @update:model-value="value=>setOverride(row,'actual_base_salary',value)" inputmode="decimal" :disabled="!sheet.can_edit" size="small" class="cell-number"><template #prefix>￥</template></el-input></template></el-table-column><el-table-column label="工作日加班" width="112"><template #default="{ row }"><el-input :model-value="weekdayOvertimePay(row)" @update:model-value="value=>setOverride(row,'weekday_overtime_pay',value)" inputmode="decimal" :disabled="!sheet.can_edit" size="small" class="cell-number"><template #prefix>￥</template></el-input></template></el-table-column><el-table-column label="休息日加班" width="112"><template #default="{ row }"><el-input :model-value="restdayOvertimePay(row)" @update:model-value="value=>setOverride(row,'restday_overtime_pay',value)" inputmode="decimal" :disabled="!sheet.can_edit" size="small" class="cell-number"><template #prefix>￥</template></el-input></template></el-table-column><el-table-column label="岗位补贴" width="108"><template #default="{ row }"><el-input :model-value="actualComponent(row,'position_allowance')" @update:model-value="value=>setOverride(row,'actual_position_allowance',value)" inputmode="decimal" :disabled="!sheet.can_edit" size="small" class="cell-number"><template #prefix>￥</template></el-input></template></el-table-column><el-table-column label="绩效工资" width="108"><template #default="{ row }"><el-input :model-value="actualComponent(row,'performance_salary')" @update:model-value="value=>setOverride(row,'actual_performance_salary',value)" inputmode="decimal" :disabled="!sheet.can_edit" size="small" class="cell-number"><template #prefix>￥</template></el-input></template></el-table-column><el-table-column label="全勤奖" width="104"><template #default="{ row }"><el-input :model-value="actualComponent(row,'attendance_bonus')" @update:model-value="value=>setOverride(row,'actual_attendance_bonus',value)" inputmode="decimal" :disabled="!sheet.can_edit" size="small" class="cell-number"><template #prefix>￥</template></el-input></template></el-table-column><el-table-column label="房补" width="104"><template #default="{ row }"><el-input :model-value="actualComponent(row,'housing_allowance')" @update:model-value="value=>setOverride(row,'actual_housing_allowance',value)" inputmode="decimal" :disabled="!sheet.can_edit" size="small" class="cell-number"><template #prefix>￥</template></el-input></template></el-table-column></el-table-column>
        <el-table-column label="兼职工资"><el-table-column label="小时数" width="100"><template #default="{ row }"><el-input v-model="row.part_time_hours" inputmode="decimal" :disabled="!sheet.can_edit" size="small" class="cell-number" /></template></el-table-column><el-table-column label="统一工价" width="110"><template #default="{ row }"><span>￥{{ n(row.part_time_hourly_rate).toFixed(2) }}</span></template></el-table-column><el-table-column label="兼职工资" width="110"><template #default="{ row }"><el-input :model-value="partTimePay(row)" @update:model-value="value=>setOverride(row,'part_time_salary',value)" inputmode="decimal" :disabled="!sheet.can_edit" size="small" class="cell-number"><template #prefix>￥</template></el-input></template></el-table-column></el-table-column>
        <el-table-column label="奖罚"><el-table-column v-for="column in monthlyColumns.slice(0,4)" :key="column.key" :label="column.label" width="110"><template #default="{ row }"><el-input v-model="row[column.key]" inputmode="decimal" :disabled="!sheet.can_edit" size="small" class="cell-number" /></template></el-table-column></el-table-column><el-table-column label="应发工资" width="118"><template #default="{ row }"><b class="gross">￥{{ grossSalary(row).toFixed(2) }}</b></template></el-table-column>
        <el-table-column label="代扣代缴"><el-table-column v-for="column in monthlyColumns.slice(4)" :key="column.key" :label="column.label" width="110"><template #default="{ row }"><el-input v-model="row[column.key]" inputmode="decimal" :disabled="!sheet.can_edit_deductions" size="small" class="cell-number" /></template></el-table-column></el-table-column><el-table-column label="实发工资" width="118"><template #default="{ row }"><b class="net">￥{{ netSalary(row).toFixed(2) }}</b></template></el-table-column><el-table-column label="银行卡信息"><el-table-column prop="bank_card_number" label="银行卡号" width="178" /><el-table-column prop="bank_name" label="开户行" width="170" /><el-table-column prop="id_card_number" label="身份证号" width="190" /><el-table-column prop="phone" label="手机号" width="130" /></el-table-column>
      </el-table></div><p v-if="sheet.review_reason" class="review-note">审核意见：{{ sheet.review_reason }}</p><p class="sheet-footnote">标准工资只读；出勤、计薪天数和实际工资可调整，应发、实发合计自动计算。代扣代缴由高权限人员填写。支援身份及登记日期由人事维护，工资按各门店承担金额汇总。</p><el-table v-if="sheet.events?.length" :data="sheet.events" size="small" class="audit-events"><el-table-column prop="created_at" label="时间" width="175" /><el-table-column prop="actor_name" label="操作人" width="120" /><el-table-column prop="action" label="操作" width="130" /><el-table-column prop="note" label="说明" /></el-table></section>
    <section v-else-if="!detailOnly" class="empty-sheet card-compact"><h3>{{ reviewOnly ? '从待审核列表打开工资表' : '选择门店和工资月份开始制作' }}</h3><p>系统会生成可编辑预览，不会直接下载文件，也不会覆盖已有工资表。</p></section>
    <section v-if="!detailOnly && savedSheets.length" class="saved-sheet-list card-compact"><div class="card-header">待处理工资表（草稿 / 已保存 / 退回）</div><el-table :data="savedSheets" size="small"><el-table-column prop="period" label="月份" width="110" /><el-table-column prop="store_name" label="门店" min-width="240" /><el-table-column prop="employee_count" label="员工数" width="85" /><el-table-column prop="status" label="状态" width="90" /><el-table-column prop="updated_at" label="最后更新" width="170" /><el-table-column label="操作" width="80"><template #default="{ row }"><el-button link type="primary" @click="loadSavedSheet(row.id)">打开</el-button></template></el-table-column></el-table></section>
  </div>
</template>

<script setup>
import { computed, onMounted, reactive, ref, watch } from 'vue'
import { useRouter } from 'vue-router'
import StoreRegionSelect from '@/components/StoreRegionSelect.vue'
const router=useRouter()
const props=defineProps({reviewOnly:Boolean,detailOnly:Boolean,sheetId:[Number,String],reviewPeriod:String})
const emit=defineEmits(['changed'])
const reviewOnly=computed(()=>props.reviewOnly)
const detailOnly=computed(()=>props.detailOnly)
import { ElMessage, ElMessageBox } from 'element-plus'
import { exportPayrollSheet, getPayrollReviewSheet, getPayrollMonthSetting, getPayrollSheet, getPayrollSheets, getPayrollContext, submitPayrollSheet, reviewPayrollSheet, preparePayrollSheet, savePayrollSheet, savePayrollDeductions } from '@/api'
const stores=ref([]),savedSheets=ref([]),sheet=ref(null),preparing=ref(false),saving=ref(false),loadingSheet=ref(false),loadError=ref('')
const form=reactive({store_name:'',period:new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit'}).format(new Date()),scheduled_days:26})
const context=ref({can_prepare:false,can_attendance:false,can_standard:false,own_only:false})
const monthSettings=reactive({group:{scheduled_days:26,version:0,published_at:null},store:{scheduled_days:26,version:0,published_at:null}})
const affiliation=computed({get:()=>stores.value.find(store=>store.store_name===form.store_name)?.id || form.store_name,set:value=>{form.store_name=stores.value.find(store=>Number(store.id)===Number(value))?.store_name || value || ''}})
const attendanceColumns=[{key:'personal_leave',label:'事假'},{key:'sick_leave',label:'病假'},{key:'join_leave',label:'入/离职缺勤'},{key:'dispatch_out_days',label:'派出天数'},{key:'support_days',label:'支援天数'},{key:'annual_leave',label:'年假'},{key:'weekday_overtime_hours',label:'工作日加班时长'},{key:'restday_overtime_hours',label:'休息日加班时长'}]
const salaryColumns=[{key:'base_salary',label:'基本工资'},{key:'position_allowance',label:'岗位补贴'},{key:'performance_salary',label:'绩效工资'},{key:'attendance_bonus',label:'全勤奖'},{key:'housing_allowance',label:'房补'}]
const monthlyColumns=[{key:'reward',label:'奖励'},{key:'penalty',label:'罚款'},{key:'late_early_deduction',label:'迟到早退'},{key:'other_deduction',label:'其他扣款'},{key:'social_insurance',label:'社保'},{key:'income_tax',label:'个税'},{key:'utilities_fee',label:'水电'},{key:'uniform_deposit',label:'工衣押金'}]
const n=v=>Math.max(0,Number(v)||0)
const adjusted=(r,key,value)=>Object.hasOwn(r.salary_overrides || {},key)?n(r.salary_overrides[key]):value
const setOverride=(r,key,value)=>{r.salary_overrides={...(r.salary_overrides || {}),[key]:value}}
const actualDays=r=>adjusted(r,'actual_days',Math.max(0,n(r.scheduled_days)-n(r.personal_leave)-n(r.sick_leave)-n(r.join_leave)-n(r.dispatch_out_days)+n(r.support_days)+n(r.annual_leave)))
const standardSalary=r=>r.hire_type==='兼职'?n(r.part_time_hourly_rate):['base_salary','position_allowance','performance_salary','attendance_bonus','housing_allowance'].reduce((s,k)=>s+n(r[k]),0)
const actualComponent=(r,key)=>adjusted(r,'actual_'+key,r.hire_type==='兼职'?0:n(r[key])*actualDays(r)/Math.max(1,n(r.payroll_base_days)||n(r.scheduled_days)))
const weekdayOvertimePay=r=>adjusted(r,'weekday_overtime_pay',n(r.weekday_overtime_hours)*n(r.weekday_overtime_rate))
const restdayOvertimePay=r=>adjusted(r,'restday_overtime_pay',n(r.restday_overtime_hours)*n(r.restday_overtime_rate))
const partTimePay=r=>adjusted(r,'part_time_salary',n(r.part_time_hours)*n(r.part_time_hourly_rate))
const grossSalary=r=>['base_salary','position_allowance','performance_salary','attendance_bonus','housing_allowance'].reduce((s,k)=>s+actualComponent(r,k),0)+weekdayOvertimePay(r)+restdayOvertimePay(r)+partTimePay(r)+n(r.reward)-n(r.penalty)-n(r.late_early_deduction)-n(r.other_deduction)
const deductions=r=>['social_insurance','income_tax','utilities_fee','uniform_deposit'].reduce((s,k)=>s+n(r[k]),0)
const netSalary=r=>grossSalary(r)-deductions(r)
const summary=computed(()=> (sheet.value?.items||[]).reduce((o,r)=>({gross:o.gross+grossSalary(r),deductions:o.deductions+deductions(r),net:o.net+netSalary(r)}),{gross:0,deductions:0,net:0}))
async function loadLists(){try{if(props.detailOnly)return;const[a,b]=await Promise.all([getPayrollContext(),getPayrollSheets('work')]);context.value=a.context;stores.value=a.context.stores;savedSheets.value=b.sheets||[];if(context.value.own_only)form.store_name=stores.value[0]?.store_name || ''}catch(e){ElMessage.error('工资表资料读取失败：'+e.message)}}
async function prepareSheet(){if(!form.store_name||!form.period){ElMessage.warning('请选择员工归属和工资月份');return}preparing.value=true;try{sheet.value=(await preparePayrollSheet(form)).sheet;await loadLists();ElMessage.success('工资表已打开')}catch(e){ElMessage.error('生成失败：'+e.message)}finally{preparing.value=false}}
async function loadMonthSetting(){if(!form.period)return;try{const result=await getPayrollMonthSetting(form.period);Object.assign(monthSettings,result.settings)}catch(e){ElMessage.error('读取本月应出勤设置失败：'+e.message)}}
async function loadSavedSheet(id){loadingSheet.value=true;loadError.value='';try{sheet.value=(await (props.detailOnly?getPayrollReviewSheet(props.reviewPeriod,id):getPayrollSheet(id))).sheet;Object.assign(form,{store_name:sheet.value.store_name,period:sheet.value.period,scheduled_days:sheet.value.scheduled_days});if(!props.detailOnly)await loadMonthSetting()}catch(e){loadError.value='打开失败：'+e.message;ElMessage.error(loadError.value)}finally{loadingSheet.value=false}}
async function persistSheet(){sheet.value=(await savePayrollSheet(sheet.value.id,{version:sheet.value.version,items:sheet.value.items})).sheet;await loadLists()}
async function persistDeductions(){sheet.value=(await savePayrollDeductions(sheet.value.id,{version:sheet.value.version,items:sheet.value.items.map(row=>Object.fromEntries(['id','employee_id','social_insurance','income_tax','utilities_fee','uniform_deposit'].map(key=>[key,row[key]])))})).sheet}
async function saveDeductions(){saving.value=true;try{await persistDeductions();ElMessage.success('代扣代缴已保存')}catch(e){ElMessage.error('保存失败：'+e.message)}finally{saving.value=false}}
async function saveSheet(){if(!sheet.value)return;saving.value=true;try{await persistSheet();ElMessage.success('工资表明细已保存')}catch(e){ElMessage.error('保存失败：'+e.message)}finally{saving.value=false}}
async function submitSheet(){saving.value=true;try{await persistSheet();sheet.value=(await submitPayrollSheet(sheet.value.id,{version:sheet.value.version})).sheet;await loadLists();sheet.value=null;ElMessage.success('已提交至工资审核，已从待处理列表移除')}catch(e){ElMessage.error('提交失败：'+e.message)}finally{saving.value=false}}
async function reviewSheet(action){try{let note='';if(action==='return'){const result=await ElMessageBox.prompt('请说明需修改的内容','退回工资表',{inputValidator:value=>!!value?.trim() || '请填写退回原因'});note=result.value}else await ElMessageBox.confirm('确认审核通过当前已提交工资表？通过后将锁定。','工资审核');if(sheet.value.can_edit_deductions)await persistDeductions();sheet.value=(await reviewPayrollSheet(sheet.value.id,{version:sheet.value.version,action,note})).sheet;await loadLists();emit('changed');ElMessage.success(action==='return'?'已退回，等待门店重新提交':'审核通过')}catch(e){if(e!=='cancel' && e!=='close')ElMessage.error('审核失败：'+e.message)}}
async function downloadSheet(){try{const draft=sheet.value.status!=='已审核',blob=await exportPayrollSheet(sheet.value.id,draft),href=URL.createObjectURL(blob),a=document.createElement('a');a.href=href;a.download=`${sheet.value.store_name}-${sheet.value.period}${draft?'草稿-未审核':'已审核'}工资表.xlsx`;a.click();URL.revokeObjectURL(href)}catch(e){ElMessage.error('导出失败：'+e.message)}}
watch(()=>[props.sheetId,props.reviewPeriod],async()=>{if(props.detailOnly){sheet.value=null;if(props.sheetId)await loadSavedSheet(props.sheetId)}})
onMounted(async()=>{await loadLists();if(props.detailOnly){if(props.sheetId)await loadSavedSheet(props.sheetId)}else await loadMonthSetting()})
</script>

